import { promises as fs } from "node:fs";
import path from "node:path";
import { connection } from "next/server";
import { sha256, verifyChain, type IntegrityCheck } from "./integrity";
import type { EvalIndexEntry, EvalSummary, InvestigationIndexEntry, Report, ToolRequest } from "./types";

// Identifiers are generated by the control process as
// eval-<UTC stamp> and inv-<UTC stamp>-<6 hex>. Anything else is refused
// before it reaches the filesystem, so route params cannot traverse paths.
const EVAL_ID = /^eval-\d{8}T\d{6}Z$/;
const INV_ID = /^inv-\d{8}T\d{6}Z-[0-9a-f]{6}$/;

export function runsDir(): string {
  return process.env.BOUNDARYRUN_RUNS_DIR ?? path.resolve(process.cwd(), "..", ".runs");
}

export function isEvalId(id: string): boolean {
  return EVAL_ID.test(id);
}

export function isInvestigationId(id: string): boolean {
  return INV_ID.test(id);
}

async function readJson<T>(file: string): Promise<T | null> {
  try {
    return JSON.parse(await fs.readFile(file, "utf8")) as T;
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw err;
  }
}

async function listDirs(dir: string): Promise<string[]> {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    return entries.filter((e) => e.isDirectory()).map((e) => e.name);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }
}

function countVerdicts(summary: EvalSummary): Record<string, number> {
  const out: Record<string, number> = {};
  for (const run of summary.runs) out[run.verdict] = (out[run.verdict] ?? 0) + 1;
  return out;
}

export function toEvalIndexEntry(summary: EvalSummary): EvalIndexEntry {
  return {
    eval_id: summary.eval_id,
    scenario_id: summary.scenario_id,
    started_at: summary.started_at,
    finished_at: summary.finished_at,
    agents: summary.agents,
    arms: summary.arms,
    attacks: summary.attacks,
    repeats: summary.repeats,
    model: summary.model,
    run_count: summary.runs.length,
    error_count: summary.errors.length,
    verdicts: countVerdicts(summary),
  };
}

export function toInvestigationIndexEntry(report: Report, evalId: string | null): InvestigationIndexEntry {
  return {
    investigation_id: report.investigation_id,
    eval_id: evalId,
    scenario_id: report.scenario_id,
    arm: report.arm,
    agent_mode: report.task.agent_mode,
    attack: report.task.attack,
    autonomous: report.agent.autonomous,
    verdict: report.verdict.status,
    started_at: report.execution.started_at ?? null,
  };
}

export async function listEvals(): Promise<EvalIndexEntry[]> {
  await connection();
  const root = runsDir();
  const names = (await listDirs(root)).filter(isEvalId).sort().reverse();
  const entries: EvalIndexEntry[] = [];
  for (const name of names) {
    const summary = await readJson<EvalSummary>(path.join(root, name, "summary.json"));
    if (summary) entries.push(toEvalIndexEntry(summary));
  }
  return entries;
}

export async function getEval(id: string): Promise<EvalSummary | null> {
  await connection();
  if (!isEvalId(id)) return null;
  return readJson<EvalSummary>(path.join(runsDir(), id, "summary.json"));
}

// Investigations started directly with `boundaryrun investigate` live at
// .runs/<inv>/; those produced by `boundaryrun eval` live at .runs/<eval>/<inv>/.
async function locateInvestigation(id: string): Promise<{ dir: string; evalId: string | null } | null> {
  if (!isInvestigationId(id)) return null;
  const root = runsDir();
  const direct = path.join(/*turbopackIgnore: true*/ root, id);
  if (await readJson(path.join(direct, "report.json"))) return { dir: direct, evalId: null };
  for (const name of (await listDirs(root)).filter(isEvalId)) {
    const nested = path.join(/*turbopackIgnore: true*/ root, name, id);
    if (await readJson(path.join(nested, "report.json"))) return { dir: nested, evalId: name };
  }
  return null;
}

export async function listStandaloneInvestigations(): Promise<InvestigationIndexEntry[]> {
  await connection();
  const root = runsDir();
  const names = (await listDirs(root)).filter(isInvestigationId).sort().reverse();
  const entries: InvestigationIndexEntry[] = [];
  for (const name of names) {
    const report = await readJson<Report>(path.join(root, name, "report.json"));
    if (report) entries.push(toInvestigationIndexEntry(report, null));
  }
  return entries;
}

export interface LoadedInvestigation {
  report: Report;
  evalId: string | null;
  audit: ToolRequest[];
  auditError: string | null;
  integrity: IntegrityCheck[];
  signed: boolean;
}

// The same checks as `boundaryrun verify`, minus the HMAC (the operator key never
// belongs on the viewer). Everything is recomputed from the files on disk.
export function integrityChecks(
  report: Report,
  files: { audit: Buffer | null; patch: Buffer | null; hmac: boolean },
): IntegrityCheck[] {
  const checks: IntegrityCheck[] = [];
  for (const [name, digest] of Object.entries(report.artifacts).sort()) {
    const data = name === "audit.jsonl" ? files.audit : name === "patch.diff" ? files.patch : null;
    if (!data) {
      checks.push({ name: `artifact ${name}`, ok: false, detail: "file missing" });
      continue;
    }
    const actual = sha256(data);
    checks.push({
      name: `artifact ${name}`,
      ok: actual === digest,
      detail: actual === digest ? "sha256 matches report" : `sha256 ${actual.slice(0, 12)} differs from report ${digest.slice(0, 12)}`,
    });
  }
  if (!files.audit) {
    checks.push({ name: "audit chain", ok: false, detail: "audit.jsonl missing" });
  } else {
    const lines = files.audit.toString("utf8").split("\n").filter((l) => l.length > 0);
    const claimed = report.audit_chain_head ?? null;
    if (claimed === null) {
      checks.push({ name: "audit chain", ok: null, detail: "report predates audit chaining; only the file hash can be checked" });
    } else {
      const chain = verifyChain(lines);
      checks.push({ name: "audit chain", ok: chain.ok, detail: chain.problem ?? `${chain.records} records, head ${chain.head.slice(0, 12)}` });
      checks.push({
        name: "chain head in report",
        ok: claimed === chain.head,
        detail: claimed === chain.head ? "matches" : `report says ${claimed.slice(0, 12)}, log ends at ${chain.head.slice(0, 12)}`,
      });
      const inReport = report.tool_requests.map((r) => r.record_hash ?? null);
      const inLog = lines.map((l) => /,"record_hash":"([0-9a-f]{64})"\}$/.exec(l)?.[1] ?? null);
      const same = inReport.length === inLog.length && inReport.every((h, i) => h === inLog[i]);
      checks.push({
        name: "report tool_requests vs audit.jsonl",
        ok: same,
        detail: same ? "same records in the same order" : `${inReport.length} in report, ${inLog.length} in log, or hashes differ`,
      });
    }
  }
  if (report.patch.diff) {
    if (!files.patch) checks.push({ name: "patch.diff vs report.patch.diff", ok: false, detail: "patch.diff missing" });
    else {
      const same = files.patch.toString("utf8") === report.patch.diff;
      checks.push({ name: "patch.diff vs report.patch.diff", ok: same, detail: same ? "identical" : "the diff on disk differs from the one in the report" });
    }
  }
  checks.push({
    name: "report HMAC",
    ok: null,
    detail: files.hmac ? "report.hmac present; verify with boundaryrun verify and the operator key" : "not signed",
  });
  return checks;
}

async function readOptional(file: string): Promise<Buffer | null> {
  try {
    return await fs.readFile(file);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw err;
  }
}

export async function getInvestigation(id: string): Promise<LoadedInvestigation | null> {
  await connection();
  const located = await locateInvestigation(id);
  if (!located) return null;
  const report = (await readJson<Report>(path.join(located.dir, "report.json")))!;
  const [auditRaw, patchRaw, hmacRaw] = await Promise.all([
    readOptional(path.join(located.dir, "audit.jsonl")),
    readOptional(path.join(located.dir, "patch.diff")),
    readOptional(path.join(located.dir, "report.hmac")),
  ]);
  let audit: ToolRequest[] = [];
  let auditError: string | null = null;
  if (auditRaw === null) auditError = "audit.jsonl missing";
  else {
    try {
      audit = auditRaw
        .toString("utf8")
        .split("\n")
        .filter((line) => line.trim().length > 0)
        .map((line) => JSON.parse(line) as ToolRequest);
    } catch (err) {
      auditError = (err as Error).message;
    }
  }
  const integrity = integrityChecks(report, { audit: auditRaw, patch: patchRaw, hmac: hmacRaw !== null });
  return { report, evalId: located.evalId, audit, auditError, integrity, signed: hmacRaw !== null };
}
